#include <iostream>
#include <string>
#include <vector>

using namespace std;

int main() {
    int num;
    string c;
    cin >> num >> c;

    vector<int> groups;

    for (int i = 0; i < static_cast<int>(c.size());) {
        if (c[i] == 'W') {
            ++i;
        } else {
            int count = 0;
            while (i < static_cast<int>(c.size()) && c[i] == 'B') {
                ++count;
                ++i;
            }
            groups.push_back(count);
        }
    }

    cout << groups.size() << '\n';
    for (int i = 0; i < static_cast<int>(groups.size()); ++i) {
        if (i > 0) cout << ' ';
        cout << groups[i];
    }
    if (!groups.empty()) cout << '\n';

    return 0;
}

